describe('Deep Links Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should load the correct page when accessing a deep link directly', () => {
    cy.visit('/products/electronics/laptops');
    cy.url().should('include', '/products/electronics/laptops');
    cy.get('h1').should('contain', 'Laptops');
    cy.get('[data-testid="breadcrumb"]').should('contain', 'Products');
    cy.get('[data-testid="breadcrumb"]').should('contain', 'Electronics');
    cy.get('[data-testid="breadcrumb"]').should('contain', 'Laptops');
  });

  it('should load the correct page with query parameters in deep link', () => {
    cy.visit('/search?q=gaming&sort=price&filter=brand:dell');
    cy.url().should('include', '/search');
    cy.url().should('include', 'q=gaming');
    cy.url().should('include', 'sort=price');
    cy.url().should('include', 'filter=brand:dell');
    cy.get('[data-testid="search-input"]').should('have.value', 'gaming');
    cy.get('[data-testid="sort-dropdown"]').should('have.value', 'price');
  });

  it('should handle deep links with special characters and encoded URLs', () => {
    cy.visit('/products/search%20results?category=home%20%26%20garden');
    cy.url().should('include', '/products/search');
    cy.get('[data-testid="page-title"]').should('be.visible');
    cy.get('[data-testid="results-container"]').should('exist');
  });

  it('should redirect to home page when accessing invalid deep link', () => {
    cy.visit('/invalid/nonexistent/path', { failOnStatusCode: false });
    cy.url().should('include', '/');
    cy.get('[data-testid="error-message"]').should('be.visible');
  });

  it('should preserve deep link state when navigating back and forward', () => {
    cy.visit('/dashboard/analytics/reports');
    cy.url().should('include', '/dashboard/analytics/reports');
    cy.get('[data-testid="report-title"]').should('contain', 'Reports');

    cy.visit('/');
    cy.url().should('not.include', '/dashboard/analytics/reports');

    cy.go('back');
    cy.url().should('include', '/dashboard/analytics/reports');
    cy.get('[data-testid="report-title"]').should('contain', 'Reports');
  });

  it('should load deep link with hash fragments correctly', () => {
    cy.visit('/documentation#section-api-reference');
    cy.url().should('include', '/documentation');
    cy.url().should('include', '#section-api-reference');
    cy.get('[data-testid="api-reference-section"]').should('be.visible');
  });
});
